package com.app.controller; import com.app.dto.SocietyAttendanceDtos.*; import com.app.security.UserPrincipal; import com.app.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/society/attendance") @RequiredArgsConstructor public class SocietyAttendanceController {private final SocietyAttendanceService service;private final SocietyAttendanceWorkflowService workflow;@GetMapping public List<AttendanceRow> day(@AuthenticationPrincipal UserPrincipal p,@RequestParam(required=false) LocalDate date){return service.day(p.getAccountId(),date==null?LocalDate.now():date);}@GetMapping("/shortages") public List<AgencyShortage> shortages(@AuthenticationPrincipal UserPrincipal p,@RequestParam(required=false) LocalDate date){return service.shortages(p.getAccountId(),date==null?LocalDate.now():date);}@PostMapping("/bulk") public List<AttendanceRow> bulk(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody BulkRequest r){workflow.ensureEditable(p.getAccountId(),r.getAttendanceDate());return service.saveBulk(p.getAccountId(),p.getUserId(),r);}}
